// Valider que les champs critiques ne sont pas vides (sans 'resume')
// Le 'resume' (ملخص) n'est plus obligatoire.
if (!$json.prenom || !$json.nom || !$json.email) {
    throw new Error("Manque des informations critiques (Prénom, Nom, Email) pour générer le CV.");
}

// S'assurer que les tableaux sont bien des tableaux et éviter les erreurs
$json.experiences = Array.isArray($json.experiences) ? $json.experiences : [];
$json.education = Array.isArray($json.education) ? $json.education : [];
$json.competences = Array.isArray($json.competences) ? $json.competences : [];
$json.langues = Array.isArray($json.langues) ? $json.langues : []; 

